import React, { useState, useEffect, useRef } from 'react';
import { useTurboProps, useTurboCache } from '../utils/turbo';

function MadminArrayFieldIsland({ containerId }) {
  const initialProps = useTurboProps(containerId);

  const [items, setItems] = useState(initialProps.items || []);
  const [newItem, setNewItem] = useState('');
  const [draggedIndex, setDraggedIndex] = useState(null);
  const inputRef = useRef(null);

  // Read fieldName and placeholder from DOM data attributes (not cached state)
  const [fieldName, setFieldName] = useState('items[]');
  const [placeholder, setPlaceholder] = useState('Enter value...');

  useEffect(() => {
    const container = document.getElementById(containerId);
    if (container) {
      const fieldNameAttr = container.getAttribute('data-field-name');
      const placeholderAttr = container.getAttribute('data-placeholder');
      if (fieldNameAttr) setFieldName(fieldNameAttr);
      if (placeholderAttr) setPlaceholder(placeholderAttr);
    }
  }, [containerId]);

  // Setup turbo cache persistence
  useEffect(() => {
    const cleanup = useTurboCache(containerId, { items }, true);
    return cleanup;
  }, [containerId, items]);

  const handleAdd = () => {
    if (newItem.trim()) {
      setItems([...items, newItem.trim()]);
      setNewItem('');
      inputRef.current?.focus();
    }
  };

  const handleRemove = (index) => {
    setItems(items.filter((_, i) => i !== index));
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleAdd();
    }
  };

  const handleDragStart = (index) => {
    setDraggedIndex(index);
  };

  const handleDragOver = (e, index) => {
    e.preventDefault();

    if (draggedIndex === null || draggedIndex === index) return;

    const newItems = [...items];
    const draggedItem = newItems[draggedIndex];

    // Remove from old position
    newItems.splice(draggedIndex, 1);
    // Insert at new position
    newItems.splice(index, 0, draggedItem);

    setItems(newItems);
    setDraggedIndex(index);
  };

  const handleDragEnd = () => {
    setDraggedIndex(null);
  };

  return (
    <div style={{
      fontFamily: 'system-ui, -apple-system, sans-serif',
      width: '100%'
    }}>
      {/* Items list with actual input fields that Rails can serialize */}
      <div style={{ marginBottom: '12px' }}>
        {items.length === 0 ? (
          <div style={{
            padding: '16px',
            textAlign: 'center',
            color: '#6b7280',
            fontSize: '14px',
            fontStyle: 'italic',
            backgroundColor: '#f9fafb',
            borderRadius: '6px',
            border: '1px dashed #d1d5db'
          }}>
            No items yet. Add your first item below.
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {items.map((item, index) => (
              <div
                key={index}
                draggable
                onDragStart={() => handleDragStart(index)}
                onDragOver={(e) => handleDragOver(e, index)}
                onDragEnd={handleDragEnd}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '8px',
                  padding: '10px 12px',
                  backgroundColor: draggedIndex === index ? '#e0e7ff' : '#ffffff',
                  border: '1px solid #d1d5db',
                  borderRadius: '6px',
                  cursor: 'grab',
                  transition: 'all 0.2s',
                  boxShadow: draggedIndex === index ? '0 4px 12px rgba(0,0,0,0.1)' : 'none'
                }}
              >
                <div style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: '20px',
                  height: '20px',
                  color: '#9ca3af',
                  cursor: 'grab',
                  fontSize: '16px'
                }}>
                  ⋮⋮
                </div>

                {/* Actual hidden input that Rails will serialize */}
                <input
                  type="hidden"
                  name={fieldName}
                  value={item}
                />

                <div style={{
                  flex: 1,
                  fontSize: '14px',
                  color: '#1f2937',
                  userSelect: 'none'
                }}>
                  {item}
                </div>

                <button
                  type="button"
                  onClick={() => handleRemove(index)}
                  style={{
                    padding: '4px 10px',
                    backgroundColor: '#fee2e2',
                    color: '#dc2626',
                    border: '1px solid #fecaca',
                    borderRadius: '4px',
                    cursor: 'pointer',
                    fontSize: '12px',
                    fontWeight: '500',
                    transition: 'all 0.2s'
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.backgroundColor = '#fecaca';
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.backgroundColor = '#fee2e2';
                  }}
                >
                  Remove
                </button>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Add new item */}
      <div style={{
        display: 'flex',
        gap: '8px',
        padding: '12px',
        backgroundColor: '#f9fafb',
        borderRadius: '6px',
        border: '1px solid #e5e7eb'
      }}>
        <input
          ref={inputRef}
          type="text"
          value={newItem}
          onChange={(e) => setNewItem(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          style={{
            flex: 1,
            padding: '8px 12px',
            border: '1px solid #d1d5db',
            borderRadius: '6px',
            fontSize: '14px',
            outline: 'none',
            transition: 'border-color 0.2s'
          }}
          onFocus={(e) => {
            e.currentTarget.style.borderColor = '#4f46e5';
          }}
          onBlur={(e) => {
            e.currentTarget.style.borderColor = '#d1d5db';
          }}
        />
        <button
          type="button"
          onClick={handleAdd}
          style={{
            padding: '8px 16px',
            backgroundColor: '#4f46e5',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '14px',
            fontWeight: '500',
            transition: 'all 0.2s',
            whiteSpace: 'nowrap'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = '#4338ca';
            e.currentTarget.style.transform = 'translateY(-1px)';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = '#4f46e5';
            e.currentTarget.style.transform = 'translateY(0)';
          }}
        >
          + Add
        </button>
      </div>

      {items.length > 0 && (
        <div style={{
          marginTop: '8px',
          fontSize: '12px',
          color: '#6b7280',
          fontStyle: 'italic'
        }}>
          💡 Drag items to reorder
        </div>
      )}
    </div>
  );
}

export default MadminArrayFieldIsland;
