import { useState, useEffect, useCallback, useRef } from 'react'
import { sanitizeMessages, normalizeContent } from '../components/chat/types'

export function useTurboChat(
  chatId,
  options = {}
) {
  const {
    selectors = {},
    debug = false
  } = options

  const messageListSelector = selectors.messageList || '#messages'
  const messageWrapperSelector = selectors.messageWrapper || ((id) => `#message-${id}`)
  const messageContentSelector = selectors.messageContent || ((id) => `#message_${id}_content`)

  const [messages, setMessages] = useState([])
  const [isProcessing, setIsProcessing] = useState(false)
  const [isSending, setIsSending] = useState(false)

  const messagesIndexRef = useRef(new Map())
  const contentObserversRef = useRef(new Map())
  const lastContentLengthRef = useRef(new Map())

  const log = useCallback((...args) => {
    if (debug) console.log('[useTurboChat]', ...args)
  }, [debug])

  const hydrateMessagesFromDOM = useCallback(() => {
    const listEl = document.querySelector(messageListSelector)
    if (!listEl) return []

    const items = []
    listEl.querySelectorAll("[id^='message-'][data-message]").forEach((el) => {
      try {
        const payload = JSON.parse(el.getAttribute('data-message') || '{}')
        const id = Number(payload.id)
        if (!Number.isFinite(id)) return

        if (payload.role === 'user' && payload.user_submitted === false) {
          log('Skipping non-user-submitted message:', id)
          return
        }

        const contentEl = document.querySelector(messageContentSelector(id))
        let content = contentEl?.getAttribute('data-raw-content') || payload.content || ''
        content = normalizeContent(content)

            const mentions = Array.isArray(payload.mentions)
          ? payload.mentions.map((m) => ({
              id: String(m.id || ''),  // Prefixed ID (chat_xxx)
              model: String(m.model || ''),
              label: String(m.label || ''),
              path: m.path,
              avatar: m.avatar,
              metadata: m.metadata
            }))
          : []

        items.push({
          id,
          role: payload.role || 'assistant',
          content,
          mentions,
          attachments: payload.attachments || [],
          aiProcessing: Boolean(payload.ai_processing || payload.aiProcessing),
          metadata: payload.metadata || {},
          user: payload.user || null,
          createdAt: payload.created_at,
          updatedAt: payload.updated_at
        })
      } catch (err) {
        log('Failed to parse message:', err)
      }
    })

    return sanitizeMessages(items, 'hydrate')
  }, [messageListSelector, messageContentSelector, log])

  const attachContentObserver = useCallback((id) => {
    const existing = contentObserversRef.current.get(id)
    if (existing) return

    const contentEl = document.querySelector(messageContentSelector(id))
    if (!contentEl) return

    const observer = new MutationObserver(() => {
      let raw = contentEl.getAttribute('data-raw-content') || ''
      raw = normalizeContent(raw)

      const lastLen = lastContentLengthRef.current.get(id) || 0
      if (raw.length < lastLen) return

      setMessages((prev) => {
        const idx = messagesIndexRef.current.get(id)
        if (idx == null || idx >= prev.length) return prev

        const existing = prev[idx]

        if (existing.role === 'user') return prev

        const next = [...prev]
        next[idx] = { ...next[idx], content: raw }
        lastContentLengthRef.current.set(id, raw.length)
        return next
      })
    })

    observer.observe(contentEl, {
      childList: true,
      subtree: true,
      characterData: true,
      attributes: true,
      attributeFilter: ['data-raw-content']
    })

    contentObserversRef.current.set(id, observer)
  }, [messageContentSelector])

  useEffect(() => {
    const listEl = document.querySelector(messageListSelector)
    if (!listEl) {
      log('List element not found:', messageListSelector)
      return
    }

    log('Attaching list observer to:', messageListSelector)

    const listObserver = new MutationObserver((mutations) => {
      log(`Observed ${mutations.length} mutations`)
      const addedMessages = []
      const removedIds = new Set()
      const addedIds = new Set()

      for (const mutation of mutations) {
        if (mutation.type === 'childList') {
          mutation.removedNodes.forEach((node) => {
            if (node instanceof HTMLElement && node.id?.startsWith('message-')) {
              const id = parseInt(node.id.replace(/^message-(\d+).*$/, '$1'), 10)
              if (Number.isFinite(id)) removedIds.add(id)
            }
          })

          mutation.addedNodes.forEach((node) => {
            if (!(node instanceof HTMLElement)) return
            if (!node.id?.startsWith('message-')) return

            const json = node.getAttribute('data-message')
            if (!json) return

            try {
              const payload = JSON.parse(json)
              const id = Number(payload.id)
              if (!Number.isFinite(id)) return

              addedIds.add(id)

              if (messagesIndexRef.current.has(id)) {
                attachContentObserver(id)
                return
              }

              const contentEl = document.querySelector(messageContentSelector(id))
              let content = contentEl?.getAttribute('data-raw-content') || payload.content || ''
              content = normalizeContent(content)

              const mentions = Array.isArray(payload.mentions)
                ? payload.mentions.map((m) => ({
                    id: String(m.id || ''),  // Prefixed ID (chat_xxx)
                    model: String(m.model || ''),
                    label: String(m.label || ''),
                    path: m.path,
                    avatar: m.avatar,
                    metadata: m.metadata
                  }))
                : []

              const newMsg = {
                id,
                role: payload.role || 'assistant',
                content,
                mentions,
                attachments: payload.attachments || [],
                aiProcessing: Boolean(payload.ai_processing || payload.aiProcessing),
                metadata: payload.metadata || {},
                user: payload.user || null,
                createdAt: payload.created_at,
                updatedAt: payload.updated_at,
                needsReconciliation: payload.role === 'user'
              }

              log('Adding message to state:', { id: newMsg.id, role: newMsg.role, contentLength: newMsg.content.length })
              addedMessages.push(newMsg)
            } catch (err) {
              log('Failed to parse added message:', err)
            }
          })
        }
      }

      if (addedMessages.length > 0 || removedIds.size > 0) {
        log(`Applying updates: ${addedMessages.length} added, ${removedIds.size} removed`)

        setMessages((prev) => {
          let next = [...prev]
          const idx = new Map(messagesIndexRef.current)

          addedMessages.forEach((msg) => {
            // Try to reconcile user messages with optimistic placeholders
            if (msg.needsReconciliation && msg.role === 'user') {
              const recentThreshold = Date.now() - 10000
              let oldestIdx = -1
              let oldestTime = Infinity

              next.forEach((m, i) => {
                if (m.role === 'user' && m.id < 0) {
                  const msgTime = new Date(m.createdAt || 0).getTime()
                  if (msgTime > recentThreshold && msgTime < oldestTime) {
                    oldestTime = msgTime
                    oldestIdx = i
                  }
                }
              })

              if (oldestIdx !== -1) {
                const oldId = next[oldestIdx].id
                log(`Reconciled optimistic ${oldId} → real ${msg.id}`)

                // Replace optimistic message with complete server message
                next[oldestIdx] = {
                  ...msg,
                  isOptimistic: false
                }

                idx.delete(oldId)
                idx.set(msg.id, oldestIdx)
                return // Skip adding as new message
              }
            }

            // Add as new message if not reconciled
            if (!idx.has(msg.id)) {
              idx.set(msg.id, next.length)
              next.push(msg)
            }
          })

          const trueRemovals = new Set(
            [...removedIds].filter(id => !addedIds.has(id))
          )

          if (trueRemovals.size > 0) {
            next = next.filter(m => {
              if (trueRemovals.has(m.id)) {
                return m.role === 'user'
              }
              return true
            })

            const newIdx = new Map()
            next.forEach((m, i) => newIdx.set(m.id, i))
            messagesIndexRef.current = newIdx
          } else {
            messagesIndexRef.current = idx
          }

          return next
        })

        addedMessages.forEach((msg) => attachContentObserver(msg.id))
      }
    })

    listObserver.observe(listEl, {
      childList: true,
      subtree: true,
      attributes: true,
      characterData: true
    })

    return () => {
      listObserver.disconnect()
    }
  }, [messageListSelector, messageContentSelector, attachContentObserver, log])

  useEffect(() => {
    const initialMessages = hydrateMessagesFromDOM()
    setMessages(initialMessages)

    const idx = new Map()
    initialMessages.forEach((m, i) => idx.set(m.id, i))
    messagesIndexRef.current = idx

    initialMessages.forEach((m) => attachContentObserver(m.id))
  }, [hydrateMessagesFromDOM, attachContentObserver])

  useEffect(() => {
    const safe = sanitizeMessages(messages, 'processing-check')
    const processing = safe.some((m) => m.aiProcessing)
    setIsProcessing(processing)
  }, [messages])

  /**
   * Substitute @label mentions with <@id> placeholders
   * Mirrors server-side MessagesController#substitute_mentions
   * This allows optimistic messages to render mentions correctly
   */
  const substituteMentions = useCallback((content, mentions) => {
    let result = content

    mentions.forEach(mention => {
      const label = mention.label
      const stableId = mention.id || mention.metadata?.id

      if (label && stableId) {
        const escapedLabel = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
        result = result.replace(new RegExp(`@${escapedLabel}`, 'g'), `<@${stableId}>`)
      }
    })

    return result
  }, [])

  const sendMessage = useCallback(async (content, options) => {
    const mentions = options?.mentions || []
    const attachments = options?.attachments || []
    const hasAttachments = attachments.length > 0

    if (!chatId || isSending) return
    if (!content.trim() && !hasAttachments) return

    // Transform content: @label → <@id> (mirrors server-side substitute_mentions)
    // This ensures optimistic rendering matches final server response
    const processedContent = substituteMentions(content.trim(), mentions)

    const optimisticId = -Date.now()
    const optimisticMsg = {
      id: optimisticId,
      role: 'user',
      content: processedContent,
      mentions,
      attachments: [], // Will be populated after upload
      aiProcessing: false,
      metadata: {},
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      isOptimistic: true
    }

    setMessages((prev) => {
      const next = [...prev, optimisticMsg]
      const idx = new Map(messagesIndexRef.current)
      idx.set(optimisticId, next.length - 1)
      messagesIndexRef.current = idx
      return next
    })

    setIsSending(true)

    try {
      const token = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || ''

      let response

      if (hasAttachments) {
        const formData = new FormData()
        formData.append('chat_id', String(chatId))
        formData.append('content', content.trim())
        mentions.forEach(m => {
          formData.append('mentions[]', JSON.stringify({
            id: m.id || m.metadata?.id,
            model: m.model,
            label: m.label,
            path: m.path || m.metadata?.path
          }))
        })
        attachments.forEach(file => {
          formData.append('attachments[]', file)
        })

        response = await fetch('/messages', {
          method: 'POST',
          headers: {
            'Accept': 'application/json',
            'X-Requested-With': 'XMLHttpRequest',
            'X-CSRF-Token': token
          },
          body: formData
        })
      } else {
        response = await fetch('/messages', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'X-Requested-With': 'XMLHttpRequest',
            'X-CSRF-Token': token
          },
          body: JSON.stringify({
            chat_id: chatId,
            content: content.trim(),
            mentions: mentions.map(m => ({
              id: m.id || m.metadata?.id,
              model: m.model,
              label: m.label,
              path: m.path || m.metadata?.path
            }))
          })
        })
      }

      if (response.ok) {
        try {
          const data = await response.json()
          const realId = data.message_id

          if (realId && Number.isFinite(realId)) {
            setMessages((prev) => {
              if (messagesIndexRef.current.has(realId)) {
                log('Fetch reconciliation skipped - observer handled it')
                return prev
              }

              const optimisticIdx = prev.findIndex(m => m.id === optimisticId)
              if (optimisticIdx !== -1) {
                const next = [...prev]

                // Use server message data if available, otherwise just update ID
                if (data.message) {
                  next[optimisticIdx] = {
                    ...data.message,
                    isOptimistic: false
                  }
                  log(`Fetch reconciled ${optimisticId} → ${realId} with server data`)
                } else {
                  next[optimisticIdx] = {
                    ...next[optimisticIdx],
                    id: realId,
                    isOptimistic: false
                  }
                  log(`Fetch reconciled ${optimisticId} → ${realId}`)
                }

                const idx = new Map(messagesIndexRef.current)
                idx.delete(optimisticId)
                idx.set(realId, optimisticIdx)
                messagesIndexRef.current = idx

                return next
              }

              return prev
            })
          }
        } catch (err) {
          log('Failed to parse response:', err)
        }
      } else {
        log('Send failed:', response.status)
        setMessages((prev) => {
          const next = prev.filter(m => m.id !== optimisticId)
          const idx = new Map()
          next.forEach((m, i) => idx.set(m.id, i))
          messagesIndexRef.current = idx
          return next
        })
      }
    } catch (err) {
      log('Send error:', err)
      setMessages((prev) => {
        const next = prev.filter(m => m.id !== optimisticId)
        const idx = new Map()
        next.forEach((m, i) => idx.set(m.id, i))
        messagesIndexRef.current = idx
        return next
      })
    } finally {
      setIsSending(false)
    }
  }, [chatId, isSending, messageContentSelector, log, substituteMentions])

  useEffect(() => {
    return () => {
      contentObserversRef.current.forEach((obs) => {
        try { obs.disconnect() } catch {}
      })
      contentObserversRef.current.clear()
    }
  }, [])

  return {
    messages,
    sendMessage,
    isProcessing
  }
}

export default useTurboChat
